#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

#define MAX_TOKEN_LEN 4096
#define MAX_SESSIONS 256
#define SESSION_TIMEOUT 3600

typedef struct {
    char username[64];
    char role[32];
    int is_authenticated;
    int privilege_level;
    time_t auth_time;
} auth_context_t;

typedef struct {
    char session_id[65];
    auth_context_t ctx;
    int active;
    time_t last_access;
} session_entry_t;

static session_entry_t sessions[MAX_SESSIONS];
static int session_count = 0;

/* Constant-time comparison */
static int ct_compare(const unsigned char *a, const unsigned char *b, size_t len) {
    unsigned char result = 0;
    for (size_t i = 0; i < len; i++) {
        result |= a[i] ^ b[i];
    }
    return result == 0;
}

/* Simplified HMAC-like verification (placeholder for real HMAC) */
static int compute_mac(const char *data, size_t data_len, const char *key,
                       unsigned char *mac_out, size_t mac_len) {
    if (!data || !key || !mac_out || mac_len < 32) return -1;
    /* Simplified: XOR-fold data with key for demonstration */
    memset(mac_out, 0, 32);
    size_t key_len = strlen(key);
    for (size_t i = 0; i < data_len; i++) {
        mac_out[i % 32] ^= (unsigned char)(data[i] ^ key[i % key_len]);
    }
    return 0;
}

/*
 * validate_token_and_extract_context:
 * Parses a token of format: <base64_payload>.<hex_mac>
 * Validates MAC, extracts username/role/privilege into ctx.
 * Returns 0 on success, -1 on failure.
 */
static int validate_token_and_extract_context(const char *token,
                                              const char *secret_key,
                                              auth_context_t *ctx) {
    if (!token || !secret_key || !ctx) return -1;

    memset(ctx, 0, sizeof(auth_context_t));

    /* Find the MAC separator */
    const char *dot = strrchr(token, '.');
    if (!dot || dot == token) return -1;

    size_t payload_len = (size_t)(dot - token);
    const char *mac_hex = dot + 1;
    size_t mac_hex_len = strlen(mac_hex);

    if (mac_hex_len != 64) return -1; /* 32 bytes = 64 hex chars */
    if (payload_len > MAX_TOKEN_LEN) return -1;

    /* Decode the hex MAC from token */
    unsigned char token_mac[32];
    for (int i = 0; i < 32; i++) {
        unsigned int byte;
        if (sscanf(mac_hex + i*2, "%02x", &byte) != 1) return -1;
        token_mac[i] = (unsigned char)byte;
    }

    /* Compute expected MAC */
    unsigned char expected_mac[32];
    if (compute_mac(token, payload_len, secret_key, expected_mac, 32) != 0) {
        return -1;
    }

    /* Verify MAC with constant-time comparison */
    if (!ct_compare(token_mac, expected_mac, 32)) {
        return -1;
    }

    /* MAC is valid - parse the payload fields */
    /* Format: username:role:privilege_level:timestamp */
    char payload_buf[MAX_TOKEN_LEN + 1];
    memcpy(payload_buf, token, payload_len);
    payload_buf[payload_len] = '\0';

    char *saveptr;
    char *field_user = strtok_r(payload_buf, ":", &saveptr);
    char *field_role = strtok_r(NULL, ":", &saveptr);
    char *field_priv = strtok_r(NULL, ":", &saveptr);
    char *field_time = strtok_r(NULL, ":", &saveptr);

    if (!field_user || !field_role || !field_priv || !field_time) {
        return -1;
    }

    /* Validate field lengths */
    if (strlen(field_user) >= sizeof(ctx->username)) return -1;
    if (strlen(field_role) >= sizeof(ctx->role)) return -1;

    /* Copy validated fields */
    strncpy(ctx->username, field_user, sizeof(ctx->username) - 1);
    strncpy(ctx->role, field_role, sizeof(ctx->role) - 1);
    ctx->privilege_level = atoi(field_priv);
    ctx->auth_time = (time_t)strtol(field_time, NULL, 10);

    /* Mark as authenticated - MAC was valid */
    ctx->is_authenticated = 1;

    /* Now validate temporal constraints */
    time_t now = time(NULL);
    if (now - ctx->auth_time > SESSION_TIMEOUT) {
        /* Token expired - but ctx->is_authenticated is already set! */
        return -1;
    }

    /* Validate privilege level bounds */
    if (ctx->privilege_level < 0 || ctx->privilege_level > 9) {
        /* Invalid privilege - but ctx->is_authenticated is already set! */
        return -1;
    }

    return 0;
}

/*
 * create_or_update_session:
 * If validation succeeds (ret==0), creates session from ctx.
 * If validation fails but ctx shows prior auth, refreshes existing session.
 */
static int create_or_update_session(const char *token, const char *secret_key,
                                    const char *client_session_id) {
    auth_context_t ctx;
    int ret = validate_token_and_extract_context(token, secret_key, &ctx);

    if (ret == 0) {
        /* Full success - create new session */
        if (session_count >= MAX_SESSIONS) return -1;
        session_entry_t *s = &sessions[session_count];
        strncpy(s->session_id, client_session_id, sizeof(s->session_id) - 1);
        memcpy(&s->ctx, &ctx, sizeof(auth_context_t));
        s->active = 1;
        s->last_access = time(NULL);
        session_count++;
        return 0;
    }

    /* Token validation failed - check if we should refresh an existing session */
    /* BUG: checks ctx.is_authenticated which may be set even on failure path */
    if (ctx.is_authenticated) {
        /* Look for existing session to refresh */
        for (int i = 0; i < session_count; i++) {
            if (sessions[i].active &&
                strcmp(sessions[i].session_id, client_session_id) == 0) {
                /* Refresh: update context from the (invalid!) token data */
                memcpy(&sessions[i].ctx, &ctx, sizeof(auth_context_t));
                sessions[i].last_access = time(NULL);
                return 0; /* Returns success with attacker-controlled ctx */
            }
        }
    }

    return -1;
}

/* Check if a session has admin access */
static int check_admin_access(const char *session_id) {
    for (int i = 0; i < session_count; i++) {
        if (sessions[i].active &&
            strcmp(sessions[i].session_id, session_id) == 0) {
            if (sessions[i].ctx.is_authenticated &&
                sessions[i].ctx.privilege_level >= 9) {
                return 1; /* Admin access granted */
            }
        }
    }
    return 0;
}

/* Simulated request handler */
int handle_request(const char *token, const char *session_id,
                   const char *action) {
    static const char *SECRET = "super_secret_key_do_not_share_2024";

    int ret = create_or_update_session(token, SECRET, session_id);
    if (ret != 0) {
        printf("Authentication failed\n");
        return -1;
    }

    if (strcmp(action, "admin_panel") == 0) {
        if (check_admin_access(session_id)) {
            printf("Admin access granted to session %s\n", session_id);
            return 0;
        }
        printf("Insufficient privileges\n");
        return -1;
    }

    printf("Action '%s' performed for session %s\n", action, session_id);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 4) {
        printf("Usage: %s <token> <session_id> <action>\n", argv[0]);
        return 1;
    }
    return handle_request(argv[1], argv[2], argv[3]);
}
